// src/core/auth/auth.module.ts
import { FastifyPluginAsync } from 'fastify';
import authRoutes from '@core/auth/auth.routes';
import webauthnRoutes from '@core/auth/webauthn.routes';

export const authModule: FastifyPluginAsync = async (fastify) => {
  await fastify.register(authRoutes);
  // SPRINT 36.3: WebAuthn step-up authentication
  await fastify.register(webauthnRoutes, { prefix: '/webauthn' });
};
